// -O2
#include <array>
#include <atomic>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <thread>
#include <vector>

template <typename T, std::size_t N>
class MpmcQueue {
    struct Slot {
        std::atomic<std::size_t> turn{0};  // 2 * lap: free for that lap's push. 2 * lap + 1: full
        T value{};
    };
public:
    bool try_push(const T& v) {
        std::size_t pos = tail_.load(std::memory_order_relaxed);
        for (;;) {
            Slot& s = slots_[pos & (N - 1)];
            const std::size_t turn = s.turn.load(std::memory_order_acquire), mine = 2 * (pos / N);
            if (turn < mine) return false;  // last lap's value is still here: full
            if (turn == mine && tail_.compare_exchange_weak(pos, pos + 1, std::memory_order_relaxed)) {
                s.value = v;                                        // the slot is ours
                s.turn.store(mine + 1, std::memory_order_release);  // full: a pop may take it
                return true;
            }  // a failed CAS has put the new tail_ in pos
            if (turn > mine) pos = tail_.load(std::memory_order_relaxed);  // another push took it
        }
    }
    bool try_pop(T& out) {
        std::size_t pos = head_.load(std::memory_order_relaxed);
        for (;;) {
            Slot& s = slots_[pos & (N - 1)];
            const std::size_t turn = s.turn.load(std::memory_order_acquire), mine = 2 * (pos / N) + 1;
            if (turn < mine) return false;  // this lap's push hasn't come: empty
            if (turn == mine && head_.compare_exchange_weak(pos, pos + 1, std::memory_order_relaxed)) {
                out = s.value;
                s.turn.store(mine + 1, std::memory_order_release);  // free for the next lap's push
                return true;
            }
            if (turn > mine) pos = head_.load(std::memory_order_relaxed);  // another pop took it
        }
    }
private:
    alignas(128) std::atomic<std::size_t> head_{0};  // the next pop's position
    alignas(128) std::atomic<std::size_t> tail_{0};  // the next push's position
    alignas(128) std::array<Slot, N> slots_;
};

int main() {
    const int64_t feeds = 4, strategies = 4, n = 250000;  // a tick travels as seq * feeds + feed
    MpmcQueue<int64_t, 1024> q;
    std::atomic<int64_t> sum{0}, out_of_order{0};
    std::vector<std::thread> strategy_threads, feed_threads;
    for (int s = 0; s < strategies; ++s) {
        strategy_threads.emplace_back([&] {
            std::vector<int64_t> last(feeds, -1);  // the last seq seen from each feed
            int64_t mine = 0, late = 0;
            for (int64_t tick = 0; tick >= 0;) {
                if (!q.try_pop(tick) || tick < 0) continue;  // empty, or the stop marker
                if (tick / feeds <= last[tick % feeds]) ++late;
                last[tick % feeds] = tick / feeds;
                mine += tick / feeds;
            }
            sum += mine, out_of_order += late;
        });
    }
    for (int f = 0; f < feeds; ++f) {
        feed_threads.emplace_back([&, f] {
            for (int64_t seq = 0; seq < n; ++seq) while (!q.try_push(seq * feeds + f)) {}
        });
    }
    for (std::thread& t : feed_threads) t.join();
    for (int s = 0; s < strategies; ++s) while (!q.try_push(-1)) {}  // one stop marker each
    for (std::thread& t : strategy_threads) t.join();
    std::cout << "sum of seqs " << sum << ", expected " << feeds * (n * (n - 1) / 2) << '\n';
    std::cout << "out of order " << out_of_order << '\n';
}

