#include <algorithm>
#include <atomic>
#include <cstdint>
#include <iostream>
#include <string>
#include <thread>
#include <vector>

constexpr uint32_t kNone = 0xFFFFFFFF;  // the end of the list

struct Slot {                            // a preallocated order slot
    std::atomic<uint32_t> next{kNone};  // the next free slot, atomic since threads race on it
};
template <uint32_t TagStep>  // each change adds TagStep to the tag: 0 makes a plain stack
struct FreeList {
    std::vector<Slot>& slots;
    std::atomic<uint64_t> head{kNone};  // the tag in the high 32 bits, a slot's index in the low
    static uint32_t index(uint64_t h) { return static_cast<uint32_t>(h); }
    static uint64_t make(uint64_t old, uint32_t i) { return ((old >> 32) + TagStep) << 32 | i; }
    void push(uint32_t i) {
        uint64_t old = head.load();
        do {
            slots[i].next.store(index(old));
        } while (!head.compare_exchange_weak(old, make(old, i)));
    }
    uint32_t pop() {
        uint64_t old = head.load();
        while (index(old) != kNone) {
            const uint32_t next = slots[index(old)].next.load();  // a pause here lets ABA in
            if (head.compare_exchange_weak(old, make(old, next))) return index(old);
        }
        return kNone;
    }
    std::string listed() const {  // the free slots in order, stopping if they loop
        std::string out;
        for (uint32_t i = index(head.load()); i != kNone && out.size() <= slots.size(); i = slots[i].next.load()) {
            out += char('A' + i);
        }
        return out;
    }
};

template <uint32_t TagStep>
void replay(const char* name) {
    std::vector<Slot> slots(3);
    FreeList<TagStep> list{slots};
    list.push(2), list.push(1), list.push(0);       // free: A B C
    uint64_t seen = list.head.load();               // thread 1 starts a pop: the head is A
    const uint32_t next = slots[0].next.load();     // and A's next is B. Then it's paused.
    const uint32_t a = list.pop(), b = list.pop();  // thread 2 takes A and B
    list.push(a);                                   // and gives A back: free is A C
    const bool won = list.head.compare_exchange_strong(seen, list.make(seen, next));  // thread 1 resumes
    if (!won) list.pop();                           // a failed CAS retries, and takes A
    std::cout << name << ": thread 1's CAS " << (won ? "won" : "failed") << ", thread 2 holds " << char('A' + b)
              << ", free " << list.listed() << '\n';
}

int main() {
    replay<0>("plain");
    replay<1>("tagged");

    std::vector<Slot> slots(4);
    FreeList<1> list{slots};
    for (uint32_t i = 0; i < 4; ++i) list.push(i);
    std::vector<std::thread> gateways;
    for (int t = 0; t < 4; ++t) {
        gateways.emplace_back([&list] {
            for (int j = 0; j < 100000; ++j) {  // take two slots, then give both back
                const uint32_t x = list.pop(), y = list.pop();
                if (x != kNone) list.push(x);
                if (y != kNone) list.push(y);
            }
        });
    }
    for (std::thread& t : gateways) t.join();
    std::string free_slots = list.listed();
    std::sort(free_slots.begin(), free_slots.end());  // the order depends on the threads, the set doesn't
    std::cout << "after 4 threads, free " << free_slots << '\n';
}

