#include <atomic>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <thread>
#include <vector>

struct Limits {
    int64_t version;
    int64_t max_qty;  // always version * 100, so a reader can check its copy
};

constexpr uint64_t kIdle = UINT64_MAX;  // the epoch of a reader that holds no pointer
struct alignas(128) ReaderSlot { std::atomic<uint64_t> epoch{kIdle}; };
struct Retired { Limits* ptr; uint64_t epoch; };  // epoch: the global epoch when it was swapped out

class Epochs {
public:
    explicit Epochs(int readers) : slots_(readers) {}
    void enter(int r) { slots_[r].epoch.store(global_.load()); }  // before loading a pointer
    void leave(int r) { slots_[r].epoch.store(kIdle); }            // after the last use
    void retire(Limits* old) { retired_.push_back({old, global_.load()}); }
    void try_advance() {  // move on once every active reader has entered this epoch
        const uint64_t e = global_.load();
        for (const ReaderSlot& s : slots_) {
            const uint64_t r = s.epoch.load();
            if (r != kIdle && r != e) return;
        }
        global_.store(e + 1);
    }
    int64_t reclaim() {  // retired in epoch e: no reader can hold it from epoch e + 2
        int64_t freed = 0;
        std::size_t kept = 0;
        for (const Retired& r : retired_) {
            if (r.epoch + 2 <= global_.load()) {
                delete r.ptr;
                ++freed;
            } else {
                retired_[kept++] = r;  // keep it for a later call
            }
        }
        retired_.resize(kept);
        return freed;
    }
private:
    std::atomic<uint64_t> global_{0};
    std::vector<ReaderSlot> slots_;
    std::vector<Retired> retired_;  // the writer's alone
};

int main() {
    const int gateways = 3, versions = 2000, orders = 100000;
    Epochs epochs(gateways);
    std::atomic<Limits*> current{new Limits{0, 0}};
    std::atomic<int64_t> bad{0};
    std::vector<std::thread> threads;
    for (int g = 0; g < gateways; ++g) {
        threads.emplace_back([&, g] {
            for (int i = 0; i < orders; ++i) {  // check each order against the current limits
                epochs.enter(g);
                const Limits* l = current.load();
                if (l->max_qty != l->version * 100) ++bad;
                epochs.leave(g);
            }
        });
    }
    int64_t freed = 0;
    for (int64_t v = 1; v <= versions; ++v) {  // the risk thread publishes new limits
        epochs.retire(current.exchange(new Limits{v, v * 100}));
        epochs.try_advance();
        freed += epochs.reclaim();
    }
    for (std::thread& t : threads) t.join();
    epochs.try_advance(), epochs.try_advance();  // no readers left: two epochs pass at once
    freed += epochs.reclaim();
    std::cout << "published " << versions << ", freed " << freed << ", bad reads " << bad << '\n';
    delete current.load();
}

