#include <atomic>
#include <cstdint>
#include <iostream>
#include <thread>
#include <vector>

struct Quote {
    int64_t bid, ask, bid_sz, ask_sz;
};

// One writer, any number of readers. Readers never write, so they never slow the writer.
class SeqLock {
public:
    void write(const Quote& q) {
        const uint64_t s = seq_.load(std::memory_order_relaxed);
        seq_.store(s + 1, std::memory_order_relaxed);  // odd: a write is under way
        std::atomic_thread_fence(std::memory_order_release);
        bid_.store(q.bid, std::memory_order_relaxed);
        ask_.store(q.ask, std::memory_order_relaxed);
        bid_sz_.store(q.bid_sz, std::memory_order_relaxed);
        ask_sz_.store(q.ask_sz, std::memory_order_relaxed);
        seq_.store(s + 2, std::memory_order_release);  // even again: done
    }
    Quote read() const {
        Quote q;
        uint64_t before = 0, after = 0;
        do {
            before = seq_.load(std::memory_order_acquire);
            q.bid = bid_.load(std::memory_order_relaxed);
            q.ask = ask_.load(std::memory_order_relaxed);
            q.bid_sz = bid_sz_.load(std::memory_order_relaxed);
            q.ask_sz = ask_sz_.load(std::memory_order_relaxed);
            std::atomic_thread_fence(std::memory_order_acquire);
            after = seq_.load(std::memory_order_relaxed);
        } while (before != after || (before & 1));  // a write overlapped: copy again
        return q;
    }

private:
    std::atomic<uint64_t> seq_{0};
    std::atomic<int64_t> bid_{0}, ask_{0}, bid_sz_{0}, ask_sz_{0};
};

Quote make_quote(int64_t i) {  // update i: the bid, a spread of 1 to 3 ticks, and sizes all follow from i
    return Quote{10000 + i, 10001 + i + i % 3, i, 2 * i};
}
bool whole(const Quote& q) {  // every field from the same update
    const Quote want = make_quote(q.bid_sz);
    return q.bid == want.bid && q.ask == want.ask && q.ask_sz == want.ask_sz;
}

int main() {
    const int strategies = 3;
    const int64_t updates = 200000;
    SeqLock top;
    top.write(make_quote(0));
    std::atomic<bool> done{false};
    std::atomic<int64_t> torn{0}, backwards{0}, saw_last{0};
    std::vector<std::thread> readers;
    for (int s = 0; s < strategies; ++s) {
        readers.emplace_back([&] {
            int64_t prev = 0;
            bool last = false;
            while (!last) {
                last = done.load(std::memory_order_acquire);  // one more read after the writer is done
                const Quote q = top.read();
                if (!whole(q)) ++torn;
                if (q.bid_sz < prev) ++backwards;
                prev = q.bid_sz;
            }
            if (prev == updates) ++saw_last;
        });
    }
    for (int64_t i = 1; i <= updates; ++i) top.write(make_quote(i));
    done.store(true, std::memory_order_release);
    for (std::thread& t : readers) t.join();
    std::cout << "torn " << torn << ", backwards " << backwards << ", saw the last update " << saw_last << '\n';
}

